        class Common:
            @declared_attr
            def id(cls):
                return Column(Integer, primary_key=True)

            @declared_attr
            def type(cls):
                return Column(String, nullable=False)

            @declared_attr
            def __mapper_args__(cls):
                return {'polymorphic_on': cls.type}

        Base = declarative_base()

        class _A(Base, Common):
            __tablename__ = 'a'
            b = relationship('_B', back_populates='a')

        class _B(Base, Common):
            __tablename__ = 'b'
            a_id = Column(Integer, ForeignKey(_A.id))
            a = relationship(_A, back_populates='b')

        class _C(Base, Common):
            __tablename__ = 'c'
            b_id = Column(Integer, ForeignKey(_B.id))

        class A1(_A):
            __mapper_args__ = {'polymorphic_identity': 'A1'}

        class B1(_B):
            __mapper_args__ = {'polymorphic_identity': 'B1'}

        class C1(_C):
            __mapper_args__ = {'polymorphic_identity': 'C1'}
            b1 = relationship(B1, backref='c1')

        configure_mappers()

        A1 = aliased(A1, name='aaa')
        B1 = aliased(B1, name='bbb')
        C1 = aliased(C1, name='ccc')

        abc = Query(A1) \
            .outerjoin(B1, A1.b).options(contains_eager(A1.b.of_type(B1))) \
            .outerjoin(C1, B1.c1).options(contains_eager(A1.b.of_type(B1), B1.c1.of_type(C1)))
        print(abc)
```

